mapper.select:
SELECT id, system_code, module_code, status FROM tb_ai_log_analysis_task
WHERE  AND log_date = #{filter.startDate}
ORDER BY id

mapper.update:
UPDATE tb_ai_log_ai_daily_report SET status = 'SENDING', send_token = #{token},
    error_message = NULL, sent_time = NULL, update_time = #{now}
WHERE id = #{record.id} AND status = #{record.status} AND update_time = #{record.updateTime}
  AND (send_token = #{record.sendToken} OR (send_token IS NULL AND #{record.sendToken} IS NULL))

UPDATE tb_ai_log_ai_daily_report SET status = #{status}, error_message = #{error},
    sent_time = CASE WHEN #{status} = 'SUCCESS' THEN #{now} ELSE NULL END, update_time = #{now}
WHERE id = #{id} AND status = 'SENDING' AND send_token = #{token}
